import{_ as a,o,c as t,ah as i}from"./chunks/framework.CRsDMGp2.js";const h=JSON.parse('{"title":"Guide — Referrer","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/apporteur-affaires.md","filePath":"src/en/guide/apporteur-affaires.md"}'),r={name:"en/guide/apporteur-affaires.md"};function n(l,e,s,c,u,d){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="guide-—-referrer" tabindex="-1">Guide — Referrer <a class="header-anchor" href="#guide-—-referrer" aria-label="Permalink to &quot;Guide — Referrer&quot;">​</a></h1><p>Track your client portfolio and your commissions.</p><h2 id="welcome-to-naia" tabindex="-1">Welcome to Naia <a class="header-anchor" href="#welcome-to-naia" aria-label="Permalink to &quot;Welcome to Naia&quot;">​</a></h2><p>Your Naia space gives you a consolidated view of the projects of clients you&#39;ve referred to edPage group.</p><h2 id="your-portfolio" tabindex="-1">Your portfolio <a class="header-anchor" href="#your-portfolio" aria-label="Permalink to &quot;Your portfolio&quot;">​</a></h2><p>Your dashboard brings together:</p><ul><li>the total number of projects in your portfolio, by status;</li><li>each project&#39;s progress (milestones reached, tasks);</li><li>your recent projects, with direct access to their page.</li></ul><p>On a project&#39;s page, you&#39;ll find the same Tracking/Collaboration/Finance tabs as other participants (within what concerns you): view shared deliverables and reports, and upload your own documents (client files, additional information) from the Documents tab.</p><h2 id="billing-and-financial-tracking" tabindex="-1">Billing and financial tracking <a class="header-anchor" href="#billing-and-financial-tracking" aria-label="Permalink to &quot;Billing and financial tracking&quot;">​</a></h2><ul><li>Track the payment schedule and billing status of your portfolio&#39;s projects (due, paid, and upcoming installments) from each project&#39;s <strong>Billing</strong> tab.</li><li>You&#39;re notified if one of your projects is suspended for non-payment.</li><li>Your dashboard shows the total of your <strong>commissions due and paid</strong>, automatically calculated on the payments actually received from your projects&#39; clients (not just the invoiced amount) — your commission rate is set by the administrator and stated in your agency agreement.</li></ul><h2 id="inviting-a-client" tabindex="-1">Inviting a client <a class="header-anchor" href="#inviting-a-client" aria-label="Permalink to &quot;Inviting a client&quot;">​</a></h2><p>From your space, you can invite a client onto the platform (<strong>Invite</strong> menu) and track their account activation. It&#39;s the only account type you can invite directly.</p><h2 id="communication" tabindex="-1">Communication <a class="header-anchor" href="#communication" aria-label="Permalink to &quot;Communication&quot;">​</a></h2><p>Talk with the internal project manager about the projects in your portfolio via built-in messaging, and receive notifications on key steps and points of concern (delay, non-payment).</p>',14)])])}const f=a(r,[["render",n]]);export{h as __pageData,f as default};
